result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "diagnoses.py", "content": """"Hierarchical code-lookup over a fictional diagnosis code table.

Educational example only -- all codes are fictional.
"""

TABLE = {
    "Z00": "General exam",
    "Z00.1": "Routine child exam",
    "Z00.12": "Routine child exam, abnormal findings",
    "Z00.129": "Routine child exam detail",
    "A10": "Example infection group",
    "A10.3": "Example infection, site 3",
    "A10.31": "Example infection, site 3 variant 1",
    "A10.32": "Example infection, site 3 variant 2",
    "B20": "Example chronic group",
    "B20.9": "Example chronic, unspecified",
}


def _require(code):
    if code not in TABLE:
        raise KeyError(code)
    return code


def _build_parents():
    """X is the parent of Y iff Y startswith X, Y != X, and no code in the
    table lies strictly between them."""
    parents = {}
    codes = list(TABLE)
    for y in codes:
        best = None
        for x in codes:
            if x != y and y.startswith(x):
                if best is None or len(x) > len(best):
                    best = x
        parents[y] = best  # root codes get None
    return parents


_PARENT = _build_parents()


def parent(code):
    """Direct parent of `code`, or None for roots."""
    return _PARENT[_require(code)]


def children(code):
    """Direct children of `code` (empty list for leaves)."""
    _require(code)
    return sorted(c for c, p in _PARENT.items() if p == code)


def ancestors(code):
    """All ancestors from parent up to root."""
    _require(code)
    out = []
    p = _PARENT[code]
    while p is not None:
        out.append(p)
        p = _PARENT[p]
    return out


def descendants(code):
    """All descendants (children, grandchildren, ...)."""
    _require(code)
    out = []
    frontier = [code]
    while frontier:
        nxt = []
        for c in frontier:
            for ch in children(c):
                out.append(ch)
                nxt.append(ch)
        frontier = nxt
    return sorted(out)


def nearest_common_ancestor(a, b):
    """Deepest shared ancestor of a and b; None if none exists
    (including when they are in different branches/roots)."""
    _require(a)
    _require(b)
    anc_a = [a] + ancestors(a)
    anc_b = {x: i for i, x in enumerate([b] + ancestors(b))}
    for x in anc_a:
        if x in anc_b:
            return x
    return None


def is_a(a, b):
    """True if a == b or b is an ancestor of a."""
    _require(a)
    _require(b)
    return a == b or b in ancestors(a)


def tree():
    """Full hierarchy as nested dicts: {code: subtree}."""
    nodes = {c: {"_children": []} for c in TABLE}
    roots = []
    for c in TABLE:
        p = _PARENT[c]
        if p is None:
            roots.append(c)
        else:
            nodes[p]["_children"].append(c)

    def build(c):
        return {
            ch: build(ch) for ch in sorted(nodes[c]["_children"])
        }

    return {r: build(r) for r in sorted(roots)}


def describe(code):
    """Description string for `code`."""
    return TABLE[_require(code)]
"})
