result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_diagnoses.py", "content": "import pytest

from diagnoses import (
    TABLE,
    ancestors,
    children,
    descendants,
    describe,
    is_a,
    nearest_common_ancestor,
    parent,
    tree,
)


EXPECTED_TREE = {
    "A10": {
        "A10.3": {
            "A10.31": {},
            "A10.32": {},
        },
    },
    "B20": {
        "B20.9": {},
    },
    "Z00": {
        "Z00.1": {
            "Z00.12": {
                "Z00.129": {},
            },
        },
    },
}


def test_full_tree_shape():
    assert tree() == EXPECTED_TREE


def test_parent():
    assert parent("Z00.129") == "Z00.12"
    assert parent("Z00.12") == "Z00.1"
    assert parent("Z00.1") == "Z00"
    assert parent("A10.31") == "A10.3"
    assert parent("B20.9") == "B20"
    assert parent("A10") is None
    assert parent("Z00") is None


def test_children():
    assert children("A10.3") == ["A10.31", "A10.32"]
    assert children("Z00") == ["Z00.1"]
    assert children("B20.9") == []


def test_ancestors():
    assert ancestors("Z00.129") == ["Z00.12", "Z00.1", "Z00"]
    assert ancestors("A10.31") == ["A10.3", "A10"]
    assert ancestors("B20") == []


def test_descendants():
    d = descendants("Z00")
    assert len(d) == 3
    assert set(d) == {"Z00.1", "Z00.12", "Z00.129"}
    assert descendants("A10.3") == ["A10.31", "A10.32"]
    assert descendants("B20") == ["B20.9"]
    assert descendants("Z00.129") == []


def test_nearest_common_ancestor_siblings():
    assert nearest_common_ancestor("A10.31", "A10.32") == "A10.3"


def test_nearest_common_ancestor_across_branches_is_none():
    assert nearest_common_ancestor("A10.31", "Z00.129") is None
    assert nearest_common_ancestor("B20.9", "Z00") is None


def test_nearest_common_ancestor_related_pair():
    # Ancestor/descendant pair: NCA is the shallower one.
    assert nearest_common_ancestor("Z00", "Z00.129") == "Z00"
    assert nearest_common_ancestor("A10.31", "A10") == "A10"


def test_is_a_both_directions():
    # downward: a is-a b when b is an ancestor
    assert is_a("A10.31", "A10.3")
    assert is_a("A10.31", "A10")
    assert is_a("Z00.129", "Z00")
    # upward: not true in reverse
    assert not is_a("A10", "A10.31")
    assert not is_a("Z00", "Z00.129")
    # reflexive
    assert is_a("B20", "B20")
    # unrelated branches
    assert not is_a("A10.31", "Z00")
    assert not is_a("Z00", "A10")


@pytest.mark.parametrize("bad", ["Q99.9", "", "a10", "Z000"])
def test_unknown_code_raises_keyerror(bad):
    for fn in (
        lambda: parent(bad),
        lambda: children(bad),
        lambda: ancestors(bad),
        lambda: descendants(bad),
        lambda: nearest_common_ancestor(bad, "Z00"),
        lambda: nearest_common_ancestor("Z00", bad),
        lambda: is_a(bad, "Z00"),
        lambda: describe(bad),
    ):
        with pytest.raises(KeyError):
            fn()


def test_table_integrity():
    assert len(TABLE) == 10
"})
